CREATE COLUMN TABLE "TEST_AP"."ORCR" ("RcurCode" NVARCHAR(8) NOT NULL , "RcurDesc" NVARCHAR(50), "Frequency" NVARCHAR(1) DEFAULT 'M', "Remind" SMALLINT CS_INT DEFAULT 1, "LastPosted" LONGDATE CS_LONGDATE, "NextDeu" LONGDATE CS_LONGDATE, "EntryCount" SMALLINT CS_INT DEFAULT 0, "Volume" DECIMAL(21,6) CS_FIXED, "VolCurr" NVARCHAR(3), "FinancVol" DECIMAL(21,6) CS_FIXED, "Ref1" NVARCHAR(100), "Ref2" NVARCHAR(100), "TransCode" NVARCHAR(4), "Memo" NVARCHAR(254), "LimitRtrns" NVARCHAR(1) DEFAULT 'N', "Returns" SMALLINT CS_INT, "LimitDate" LONGDATE CS_LONGDATE, "Instance" SMALLINT CS_INT DEFAULT 0 NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "StampTax" NVARCHAR(1) DEFAULT 'N', "AutoVat" NVARCHAR(1) DEFAULT 'N', "ManageWTax" NVARCHAR(1) DEFAULT 'N', "Ref3" NVARCHAR(27), "DeferedTax" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("RcurCode", "Instance")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "ORCR_BYDATE" ON "TEST_AP"."ORCR" ( "NextDeu" ASC )